CREATE TABLE int_lock (id INTEGER PRIMARY KEY); INSERT INTO int_lock VALUES(1);
CREATE TABLE int_device (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, kind VARCHAR(16) NOT NULL CHECK(kind IN ('ATTENDANCE','CAMERA','SENSOR','SCALE')), principal VARCHAR(160) UNIQUE NOT NULL, target_id UUID, metric VARCHAR(40), unit VARCHAR(24), active BOOLEAN NOT NULL, last_seen TIMESTAMP WITH TIME ZONE, last_applied TIMESTAMP WITH TIME ZONE);
CREATE TABLE int_identity (device_id UUID NOT NULL REFERENCES int_device(id), external_person VARCHAR(80) NOT NULL, employee_id UUID NOT NULL REFERENCES mfg_employee(id), PRIMARY KEY(device_id,external_person));
CREATE TABLE int_scale_visit (device_id UUID NOT NULL REFERENCES int_device(id), visit_id UUID NOT NULL REFERENCES ops_truck_visit(id), PRIMARY KEY(device_id,visit_id));
CREATE TABLE int_event (id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES int_device(id), sequence_no BIGINT NOT NULL CHECK(sequence_no>=0), occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, payload TEXT NOT NULL, state VARCHAR(12) NOT NULL CHECK(state IN ('RECEIVED','APPLIED','IGNORED','FAILED')), attempts INTEGER NOT NULL CHECK(attempts>=0), error_code VARCHAR(80), received_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(device_id,sequence_no));
CREATE TABLE int_partner (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, kind VARCHAR(12) NOT NULL CHECK(kind IN ('CUSTOMER','SUPPLIER')), party_reference VARCHAR(160) UNIQUE NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE int_partner_user (principal VARCHAR(160) PRIMARY KEY, partner_id UUID NOT NULL REFERENCES int_partner(id), active BOOLEAN NOT NULL);
CREATE TABLE int_public_product (product_id UUID PRIMARY KEY REFERENCES catalog_product(id));
CREATE TABLE int_portal_request (id UUID PRIMARY KEY, partner_id UUID NOT NULL REFERENCES int_partner(id), kind VARCHAR(16) NOT NULL CHECK(kind IN ('SALES_REQUEST','SUPPLY_OFFER','DELIVERY_NOTICE')), reference VARCHAR(80) NOT NULL, description VARCHAR(1000) NOT NULL, lines TEXT NOT NULL, state VARCHAR(16) NOT NULL CHECK(state IN ('SUBMITTED','ACKNOWLEDGED','DECLINED')), reply VARCHAR(1000), created_by VARCHAR(160) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(partner_id,reference));
CREATE TABLE int_ai_job (id UUID PRIMARY KEY, created_by VARCHAR(160) NOT NULL, state VARCHAR(12) NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED')), input_snapshot TEXT NOT NULL, output TEXT, model VARCHAR(160), attempts INTEGER NOT NULL CHECK(attempts>=0), error_code VARCHAR(80), created_at TIMESTAMP WITH TIME ZONE NOT NULL, started_at TIMESTAMP WITH TIME ZONE, review VARCHAR(12) CHECK(review IN ('ACCEPTED','REJECTED')), reviewed_by VARCHAR(160), review_notes VARCHAR(1000));
CREATE TABLE int_audit (id UUID PRIMARY KEY, entity_id UUID NOT NULL, action VARCHAR(80) NOT NULL, actor VARCHAR(160) NOT NULL, details TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_int_events_state ON int_event(state,received_at);
CREATE INDEX ix_int_requests_partner ON int_portal_request(partner_id,created_at);
